fn solve(n: i8) -> i8 {
    // Remaining amount to decompose
    let mut rem = n;
    // Count of banknotes/coins used
    let mut count: i8 = 0;
    // Denominations in descending order
    let denoms = [100, 20, 10, 5, 1];

    for &d in denoms.iter() {
        count += rem / d;
        rem %= d;
    }

    count
}

fn main() {
    // Example usages:
    assert_eq!(solve(1), 1);    // 1×1
    assert_eq!(solve(6), 2);    // 1×5 + 1×1
    assert_eq!(solve(125), 3);  // 1×100 + 1×20 + 1×5
    assert_eq!(solve(127), 5);  // 1×100 + 1×20 + 1×5 + 2×1
    println!("All tests passed!");
}